      "rank": 1,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision measurement and tests of fundamental physics. The ability to compare optical frequencies at extraordinary accuracy is a major advance in atomic physics.",
        "attribution": "Katori's lattice trapping proposal and clock realization, alongside Ye's independent experimental advances and precision clock work, form a strong and complementary attribution.",
        "maturity": "The technique is established across laboratories, with sustained improvements and a broad record of precision measurements.",
        "uncertainties": [
          "The boundary between the foundational clock concept and later improvements is difficult to draw cleanly."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Peter Zoller",
        "Markus Greiner"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made controlled quantum many-body systems experimentally accessible, allowing direct study of phenomena that are difficult to isolate in materials.",
        "attribution": "Zoller helped establish the theoretical framework, while Bloch and Greiner led pivotal experimental demonstrations. The contribution spans theory and experiment.",
        "maturity": "The platform has been reproduced widely and has produced a substantial body of results, though its scientific program remains active.",
        "uncertainties": [
          "The long-term depth of the discoveries enabled by quantum simulation is still unfolding."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry brought coherent matter-wave methods into precision measurement, opening sensitive tests of gravity, inertial effects and fundamental physics.",
        "attribution": "Bordé, Pritchard and Kasevich represent important theoretical and experimental steps in developing atom interferometers and their precision applications.",
        "maturity": "The method has been replicated and refined across laboratories, with demonstrated scientific uses beyond the original experiments.",
        "uncertainties": [
          "The field developed through several generations of related instruments, making a sharp boundary around the credited contribution challenging."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provided a clean, tunable setting for studying pairing and the BEC–BCS crossover, connecting atomic physics with broad questions in many-body physics.",
        "attribution": "The credited experimentalists made complementary contributions to creating and probing these gases and establishing the crossover as a quantitative research platform.",
        "maturity": "The central results have been reproduced and extensively developed over many years.",
        "uncertainties": [
          "The discovery is a broad sequence of experimental advances rather than one sharply defined result."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions demonstrated that coherent quantum operations could be engineered and controlled, providing both a foundational quantum information platform and a route to quantum simulation.",
        "attribution": "Cirac and Zoller developed central theoretical proposals, while Blatt's experiments established key operations and control in ion systems.",
        "maturity": "The basic operations are robust and reproduced, although large-scale computation and its broader impact remain unsettled.",
        "uncertainties": [
          "The case depends in part on future computational capabilities that have not yet been demonstrated at scale."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Cooling and controlling molecules opened access to rich internal structure and new tests of fundamental physics, extending precision AMO methods beyond atoms.",
        "attribution": "DeMille, Doyle and Ye made major complementary contributions to trapping, cooling and controlling ultracold molecules.",
        "maturity": "Important capabilities have been demonstrated and built upon, but the experimental field is still developing.",
        "uncertainties": [
          "It is not yet clear which lasting scientific results will define this broad enabling achievement."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum key distribution connected fundamental properties of quantum measurement to a concrete, experimentally tested communication protocol.",
        "attribution": "Bennett and Brassard's protocol and Ekert's entanglement-based approach are distinct foundational contributions; the proposed three recognize the principal conceptual advances.",
        "maturity": "The principles have been experimentally demonstrated in varied settings and are technically mature, although practical security depends on implementation details.",
        "uncertainties": [
          "The extent to which deployed systems achieve the ideal security guarantees remains implementation dependent."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Gavin E. Crooks"
      ],
      "assessment": {
        "nobel_worthiness": "Exact nonequilibrium work relations gave statistical mechanics powerful results for systems driven far from equilibrium, with conceptual reach beyond their original applications.",
        "attribution": "Evans, Jarzynski and Crooks made closely related but distinguishable theoretical contributions to fluctuation relations and nonequilibrium work identities.",
        "maturity": "The relations have been tested and applied in experiments, including small-system measurements, and are well established theoretically.",
        "uncertainties": [
          "The breadth of their lasting impact on physics as a whole is less settled than their importance within nonequilibrium statistical mechanics."
        ]
      }
    }
  ]
